import{_ as t,c as a,o as n,ag as s}from"./chunks/framework.Ci10AEOF.js";const r="/docs-website/assets/settings_data_pruner.cnisgJVT.png",u=JSON.parse('{"title":"Data Pruning and Maintenance","description":"Message retention and cleanup","frontmatter":{"title":"Data Pruning and Maintenance","description":"Message retention and cleanup"},"headers":[],"relativePath":"engine/data_pruning_and_maintenance.md","filePath":"engine/data_pruning_and_maintenance.md","lastUpdated":1793057853000}'),o={name:"engine/data_pruning_and_maintenance.md"};function i(d,e,l,h,c,p){return n(),a("div",null,e[0]||(e[0]=[s('<h1 id="data-pruning-and-maintenance" tabindex="-1">Data Pruning and Maintenance <a class="header-anchor" href="#data-pruning-and-maintenance" aria-label="Permalink to &quot;Data Pruning and Maintenance&quot;">​</a></h1><p>OIE stores message data in the database. The Data Pruner removes old message data on a schedule.</p><h2 id="data-pruner" tabindex="-1">Data Pruner <a class="header-anchor" href="#data-pruner" aria-label="Permalink to &quot;Data Pruner&quot;">​</a></h2><p>The Data Pruner is a built-in plugin that automatically removes old message data based on configurable retention policies.</p><h3 id="accessing-the-data-pruner" tabindex="-1">Accessing the Data Pruner <a class="header-anchor" href="#accessing-the-data-pruner" aria-label="Permalink to &quot;Accessing the Data Pruner&quot;">​</a></h3><p>Navigate to <strong>Settings &gt; Data Pruner</strong> in the Administrator.</p><h3 id="global-settings" tabindex="-1">Global settings <a class="header-anchor" href="#global-settings" aria-label="Permalink to &quot;Global settings&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>Enable</strong></td><td>Yes or No for the data pruner (No by default), in the <strong>Schedule</strong> panel</td></tr><tr><td><strong>Schedule Type</strong></td><td>When pruning runs: an interval, a daily time, or a cron expression. An interval must be at least 1 hour and under 24 hours</td></tr><tr><td><strong>Block Size</strong></td><td>Number of messages processed per pruning batch (default 1000; range 50 to 10000)</td></tr><tr><td><strong>Prune Events</strong></td><td>Yes or No for pruning of server events</td></tr><tr><td><strong>Prune Event Age</strong></td><td>Age in days of the events to prune when event pruning is on</td></tr><tr><td><strong>Enable Archiving</strong></td><td>Enable message archiving before pruning (disabled by default), in the <strong>Archive Settings</strong> panel</td></tr><tr><td><strong>Archiver Block Size</strong></td><td>Number of messages per archiver batch (default 50; range 1 to 1000)</td></tr><tr><td><strong>Include Attachments</strong></td><td>Include message attachments in archives (disabled by default)</td></tr></tbody></table><p><img src="'+r+`" alt="The Data Pruner tab of Settings, with the Status, Schedule, Prune Settings and Archive Settings sections"></p><p>The <strong>Archive Settings</strong> panel also has <strong>Content</strong>, <strong>Encrypt</strong>, <strong>Compression</strong>, <strong>Password Protect</strong>, <strong>Root Path</strong>, and <strong>File Pattern</strong>. A <strong>Status</strong> panel shows the Current State, Current Process, Last Process, and Next Process. The task panel has <strong>Prune Now</strong>, <strong>Stop Pruner</strong>, and <strong>View Events</strong>.</p><h3 id="per-channel-pruning" tabindex="-1">Per-channel pruning <a class="header-anchor" href="#per-channel-pruning" aria-label="Permalink to &quot;Per-channel pruning&quot;">​</a></h3><p>Each channel has its own pruning settings in the <strong>Message Pruning</strong> panel on the Summary tab of the Channel Editor:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>Metadata</strong></td><td><strong>Store indefinitely</strong>, or <strong>Prune metadata older than</strong> a number of days</td></tr><tr><td><strong>Content</strong></td><td><strong>Prune when message metadata is removed</strong>, or <strong>Prune content older than</strong> a number of days (removes message content but keeps metadata). The content age cannot exceed the metadata age</td></tr><tr><td><strong>Allow message archiving</strong></td><td>Lets the Data Pruner archive this channel&#39;s messages before deletion when archiving is enabled (checked by default)</td></tr><tr><td><strong>Prune Errored Messages</strong></td><td>Include errored messages in pruning (unchecked by default)</td></tr></tbody></table><p>The pruner skips messages that are unprocessed or that have a connector message in ERROR, QUEUED, or PENDING status. Age is measured from the date the source connector received the message. <strong>Prune Errored Messages</strong> removes only ERROR from that list, so QUEUED and PENDING messages are still skipped.</p><h3 id="pruning-strategy" tabindex="-1">Pruning strategy <a class="header-anchor" href="#pruning-strategy" aria-label="Permalink to &quot;Pruning strategy&quot;">​</a></h3><p>The pruner operates in two phases:</p><ol><li><strong>Metadata Pruning</strong>: Removes entire messages (metadata, content, custom metadata, attachments, and connector messages) older than the metadata retention period</li><li><strong>Content Pruning</strong>: Removes only message content and attachments while preserving metadata, for messages older than the content retention period but newer than the metadata retention period</li></ol><p>Metadata can be kept longer than content, for example content for 7 days and metadata for 30 days.</p><h2 id="message-storage-modes" tabindex="-1">Message storage modes <a class="header-anchor" href="#message-storage-modes" aria-label="Permalink to &quot;Message storage modes&quot;">​</a></h2><p>The storage mode set on a channel decides what is stored, and the table shows which pruning applies to each mode:</p><table tabindex="0"><thead><tr><th>Mode</th><th>What&#39;s Stored</th><th>Pruning Impact</th></tr></thead><tbody><tr><td><strong>Development</strong></td><td>All content types (raw, transformed, encoded, sent, response, maps, etc.)</td><td>Largest storage footprint. Metadata and content pruning apply</td></tr><tr><td><strong>Production</strong></td><td>Raw, encoded, sent, response, and maps (excludes processed raw, transformed, response transformed, and processed response)</td><td>Moderate storage. Metadata and content pruning apply</td></tr><tr><td><strong>Raw</strong></td><td>Raw content and the source map, plus custom metadata and attachments. No other maps and no encoded, sent, or response content; message recovery and durability are disabled</td><td>Smaller storage. Metadata and content pruning apply</td></tr><tr><td><strong>Metadata</strong></td><td>Only custom metadata and attachments, no message content or maps (message recovery disabled)</td><td>Minimal storage. Metadata pruning applies</td></tr><tr><td><strong>Disabled</strong></td><td>Nothing stored</td><td>The pruner skips the channel</td></tr></tbody></table><p>Set storage mode per-channel in the channel properties.</p><h2 id="manual-message-cleanup" tabindex="-1">Manual message cleanup <a class="header-anchor" href="#manual-message-cleanup" aria-label="Permalink to &quot;Manual message cleanup&quot;">​</a></h2><h3 id="desktop-administrator" tabindex="-1">Desktop Administrator <a class="header-anchor" href="#desktop-administrator" aria-label="Permalink to &quot;Desktop Administrator&quot;">​</a></h3><ol><li>Open the <strong>Message Browser</strong> for a channel</li><li>Use filters to find messages</li><li>Click <strong>Remove All Messages</strong>, <strong>Remove Results</strong> (everything in the current search), or <strong>Remove Message</strong> (the selected one)</li></ol><h3 id="cli" tabindex="-1">CLI <a class="header-anchor" href="#cli" aria-label="Permalink to &quot;CLI&quot;">​</a></h3><p>These commands are typed at the prompt of the CLI shell, started with <code>java -jar mirth-cli-launcher.jar</code> (see <a href="./command_line_interface.html#launching-the-cli">Command Line Interface</a>). They are not operating-system commands. <code>clearallmessages</code> acts on every channel: a running channel is stopped, emptied, and started again, and statistics are kept. <code>resetstats</code> resets the current statistics of every deployed channel and its connectors. <code>resetstats lifetime</code> resets current and lifetime statistics for every channel. The shell ignores anything after <code>#</code>, so the block can be pasted as is.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Remove all messages from all channels, restarting any that are running</span></span>
<span class="line"><span>clearallmessages</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Reset current statistics</span></span>
<span class="line"><span>resetstats</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Reset current and lifetime statistics</span></span>
<span class="line"><span>resetstats lifetime</span></span></code></pre></div><h3 id="rest-api" tabindex="-1">REST API <a class="header-anchor" href="#rest-api" aria-label="Permalink to &quot;REST API&quot;">​</a></h3><p>The request below removes every message from one channel. Run it from any shell with <code>curl</code>, with <code>{channelId}</code> replaced by the channel&#39;s ID, and <code>&lt;username&gt;</code> and <code>&lt;password&gt;</code> by the account the request runs as. <code>-k</code> skips verification of the certificate the server generates for itself.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Remove all messages from one channel, restarting it if it is running</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -k</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DELETE</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;X-Requested-With: OpenIntegrationEngine&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;&lt;username&gt;:&lt;password&gt;&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;https://localhost:8443/api/channels/{channelId}/messages/_removeAll?restartRunningChannels=true&quot;</span></span></code></pre></div><p><code>restartRunningChannels</code> defaults to false, and then a deployed channel that is not stopped is skipped: the request succeeds and nothing is removed. With it set to true the channel is stopped, emptied, and started again. A stopped or undeployed channel is emptied either way. Leaving out <code>clearStatistics</code> keeps the channel&#39;s statistics, although the API documentation lists its default as true; add <code>&amp;clearStatistics=true</code> to reset them. The CLI&#39;s <code>clearallmessages</code> restarts running channels and keeps statistics.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The <code>X-Requested-With</code> header is required on all API requests. Any non-empty value is accepted.</p></div><h2 id="database-tasks" tabindex="-1">Database tasks <a class="header-anchor" href="#database-tasks" aria-label="Permalink to &quot;Database tasks&quot;">​</a></h2><p>The <strong>Settings &gt; Database Tasks</strong> panel shows available database cleanup or optimization tasks, with the columns Status, Name, Description, and Start Time. Tasks appear when applicable conditions are detected (e.g., legacy tables exist that can be removed). Select one and click <strong>Run Task</strong>, or <strong>Cancel Task</strong> to cancel it.</p><h2 id="archiving" tabindex="-1">Archiving <a class="header-anchor" href="#archiving" aria-label="Permalink to &quot;Archiving&quot;">​</a></h2><p>When archiving is enabled, the Data Pruner exports messages before deleting them:</p><ul><li>Individual messages are serialized as XML files</li><li>Files can optionally be bundled into a <code>zip</code>, <code>tar.gz</code>, or <code>tar.bz2</code> archive</li><li>The archive directory, file pattern, and compression format are all configurable</li><li>Attachment inclusion is optional (disabled by default)</li><li>Archives written in the default XML serialized message format can be imported back into a deployed channel with Import Messages in the Message Browser, with the CLI <code>importmessages</code> command, or through the message import endpoints of the REST API. A file, a folder, or an archive is accepted, and the importer reads archive entries in place</li></ul>`,38)]))}const m=t(o,[["render",i]]);export{u as __pageData,m as default};
